<?php
namespace App\Http\Controllers\Api\V1;
use App\Http\Controllers\Controller;use App\Models\Interest;use App\Services\ActivityTracker;use Illuminate\Http\Request;
class InterestController extends Controller { public function index(Request $r){return Interest::where('sender_id',$r->user()->id)->orWhere('receiver_id',$r->user()->id)->latest()->paginate(30);} public function store(Request $r,ActivityTracker $tracker){$data=$r->validate(['receiver_id'=>['required','integer','exists:users,id','not_in:'.$r->user()->id],'message'=>['nullable','string','max:500']]);$interest=Interest::firstOrCreate(['sender_id'=>$r->user()->id,'receiver_id'=>$data['receiver_id']],['message'=>$data['message']??null,'status'=>'pending']);$tracker->record($r,'interest.sent','interest',$interest->id,['receiver_id'=>$data['receiver_id']]);return response()->json($interest,201);} public function respond(Request $r,Interest $interest,ActivityTracker $tracker){abort_unless($interest->receiver_id===$r->user()->id,403);$data=$r->validate(['status'=>['required','in:accepted,declined']]);$interest->update(['status'=>$data['status'],'responded_at'=>now()]);$tracker->record($r,'interest.'.$data['status'],'interest',$interest->id);return $interest;} }
